#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024

int main(int argc, char **argv) {
    if (argc <= 1) return 0;
    const char *input = argv[1];
    size_t input_len = strlen(input);
    if (input_len > MAX_INPUT_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    char norm[MAX_INPUT_LEN + 1];
    size_t n = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (c >= 'A' && c <= 'Z')
            norm[n++] = (char)(c + 0x20);
        else if (c >= 'a' && c <= 'z')
            norm[n++] = (char)c;
        else if (c >= '0' && c <= '9')
            norm[n++] = (char)c;
    }
    norm[n] = '\0';
    int is_palindrome = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_palindrome = 0;
            break;
        }
    }
    puts(is_palindrome ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
